const input = $input.first().json;

// Webhook authentication gate: fail-closed if secret is missing or invalid
const headers = input.headers || {};
const signature = headers['x-agencydesk-signature'] || (headers['authorization'] ? headers['authorization'].replace(/^Bearer\s+/i, '') : '');
if (!$env.AUTOMATION_SECRET || signature !== $env.AUTOMATION_SECRET) {
  throw new Error('Unauthorized Google Sheets sync webhook request.');
}

// Support both direct payloads and n8n Webhook v2 nested body
const item = input.body || input;

// Loop prevention: suppress sync if triggered by agencydesk_crm
if (item['Last Synced By'] === 'agencydesk_crm' || item.last_synced_by === 'agencydesk_crm') {
  return [{ json: { should_sync: false, reason: 'Suppressed: Origin is AgencyDesk CRM' } }];
}

let rawStatus = (item['Status'] || item.status || 'new').toLowerCase().replace(/\s+/g, '_');
if (rawStatus === 'new_inquiry') rawStatus = 'new';

return [{
  json: {
    should_sync: true,
    lead_id: item['Lead ID'] || item.lead_id || null,
    contact_name: item['Contact Name'] || item.contact_name || 'Imported Lead',
    email: (item['Email'] || item.email || '').toLowerCase().trim(),
    phone: item['WhatsApp'] || item.whatsapp || item.phone || null,
    whatsapp: item['WhatsApp'] || item.whatsapp || null,
    whatsapp_opt_in: item['WhatsApp Opt-in'] === 'YES' || Boolean(item.whatsapp_opt_in),
    instagram: item['Instagram'] || item.instagram || null,
    company: item['Company'] || item.company || 'Unassigned Company',
    service: item['Service'] || item.service || 'Web & Mobile Applications',
    brief: item['Brief'] || item.brief || 'Lead entered via Google Sheets',
    budget: Number(item['Budget'] || item.budget || 0),
    status: rawStatus,
    score: Number(item['Score'] || item.score || 50),
    notes: item['Notes'] || item.notes || null,
    source: 'google_sheets',
    last_synced_by: 'sheets_user'
  }
}];

